"""Hand-reviewed explanations of GML branches. Not inferred from object names.

Each entry is an explicit review; unmatched entries remain visibly unreviewed.
The generated catalog is retained only as the source-reference index.
"""
FLAGS = {
4: ('Исключение для одного убийства в речи Андайн', 'Меняет только реплику Андайн перед боем: при kills=1 и этом флаге=1 она выбирает вариант речи без обвинения в убийствах. Сам счётчик kills, EXP и маршрут не меняются. В просмотренном коде есть чтение, но нет присваивания: конкретную жертву этот флаг не называет.', {0:'Учитывать единственное убийство в речи',1:'Не учитывать единственное убийство в этой речи'}, 'Обычного игрового действия, устанавливающего этот флаг, в коде не найдено.'),
5: ('FUN — выбор редких событий', 'Число мира, а не шанс в процентах. Определяет доступную группу редких событий. Некоторые события дополнительно сверяют General/fun в undertale.ini, бросают случайность и расходуют оба значения, записывая 0.', {0:'Событие израсходовано или FUN выключен',2:'Песня неправильного номера',40:'Странный звонок',46:'Звонок про пиццу',56:'Кошмарный кроссворд',61:'Последователь I',62:'Последователь II',63:'Последователь III',65:'Sound Test',66:'Коридор Mystery Man',80:'Клам-гёрл',81:'Клам-гёрл и особая встреча в эпилоге',90:'Гонер-кид'}, 'При создании мира игра случайно выбирает число 1–100. Точные места и дополнительные проверки — в FUN-маршруте.'),
6: ('Hard Mode в Руинах', 'Включает изменённых противников и сценарии сложного режима. Это не общий множитель сложности на всю игру. При создании персонажа флаг сбрасывается, если имя не проходит scr_hardmodename.', {0:'Обычные Руины',1:'Hard Mode (требуется совместимое имя)'}, 'Выбрать имя Frisk при создании персонажа.'),
7: ('Мир после победы над Азриэлем', 'Включает послепацифистский эпилог: другие разговоры NPC, отсутствие обычных встреч, многие FUN-персонажи исчезают. Не проходит за тебя финальный бой; установка одного флага не согласует всю историю.', {0:'До эпилога',1:'Эпилог истинного пацифиста'}, 'Пройти истинную лабораторию и финал с Азриэлем; игра также устанавливает plot=999 и flag[510]=1.'),
8: ('Отключение случайных встреч для сюжетного отрезка', 'Родительские объекты встреч уничтожаются при flag[8]=1. Используется, в частности, после звонка с письмом Андайн и в ветке Mettaton NEO; само значение не означает «пацифизм».', {0:'Разрешить обычные встречи',1:'Не создавать обычные встречи'}, 'Устанавливается сценариями соответствующих этапов; не переключатель маршрута.'),
9: ('Сколько раз Флауи выглядывал из земли', 'Счётчик завершённых появлений следящего Флауи. obj_stalkerflowey увеличивает его перед исчезновением. Не вызывает Флауи сам по себе.', {0:'Ни одного завершённого появления'}, 'Заметить и приблизиться к следящему Флауи в комнатах, где его создают сценарии.'),
11: ('Последний бой закончился бегством', 'Временная отметка результата боя. scr_runaway выставляет 1 и увеличивает общий счётчик бегств flag[24]; вход в следующий бой сбрасывает её.', {0:'Нет отметки бегства',1:'Из последнего боя убежали'}, 'Успешно выбрать «Бежать» в бою.'),
12: ('В последнем бою был убит противник', 'Служебный результат боя, а не суммарные убийства. Присваивается при killed=1 и сбрасывается на входе в бой; участвует в реакции Ториэль на учебный бой.', {0:'Нет отметки убийства',1:'Бой дал результат убийства'}, 'Убить противника; суммарные EXP/kills считаются отдельно.'),
18: ('Особая отрисовка сцены Андайн', 'При 1 obj_screen пропускает стандартные scr_begin/scr_end; сцену рисует специальный объект. Принудительное включение вне сцены может сломать изображение.', {0:'Обычная отрисовка',1:'Специальная кат-сцена'}, 'Скрипт сцены включает и выключает сам. Для постоянного сейва оставлять 0.'),
21: ('Проигрывается анимация приготовления лапши', 'Блокирует обычную обработку пропуска в контроллере боя, пока идёт последовательность лапши. Не означает, что лапша есть в инвентаре.', {0:'Обычный ввод',1:'Анимация приготовления активна'}, 'Использовать заварную лапшу в подходящем бою; объект анимации сам сбрасывает флаг.'),
22: ('Цвет имён доступных для пощады врагов', 'Настройка подсветки меню боя, которую меняет Фроггит в Руинах. Не делает врагов доступными для пощады.', {0:'Жёлтые имена',1:'Без жёлтой подсветки',2:'Розовые имена'}, 'Поговорить с Фроггитом о жёлтых именах; отказаться от жёлтого, затем попросить вернуть цвет.'),
24: ('Число успешных побегов из боя', 'scr_runaway прибавляет 1 при успешном бегстве. Не расходник и не вероятность побега.', {0:'Ни разу не убежали'}, 'Успешно выбирать «Бежать». Неотрицательный целочисленный счётчик.'),
25: ('Число пропущенных реплик', 'Увеличивается при мгновенном допечатывании текста. При значении больше 5 исчезает Фроггит, объясняющий пропуск реплик.', {0:'Подсказка ещё нужна',6:'Порог исчезновения обучающего Фроггита'}, 'Пропускать печать диалогов кнопкой отмены.'),
26: ('Принудительный уровень маршрута убийств', 'scr_murderlv сначала вычисляет прогресс по убийствам и боссам, но любое значение >0 подменяет итог этим числом. Это отладочное принуждение; оно не создаёт соответствующие убийства и не согласует сюжет.', {0:'Вычислять маршрут по настоящим событиям',1:'Руины: набрана квота',2:'Ториэль убита',7:'Сноудин: квота выполнена',8:'Папирус убит',11:'Водопадье: квота выполнена',12:'Андайн Бессмертная пройдена',15:'Хотленд/Ядро: квота выполнена',16:'Завершён набор условий убийственного маршрута'}, 'В обычном прохождении оставлять 0. Значения 1–16 возвращаются scr_murderlv по цепочке реальных условий.'),
27: ('Срыв последнего условия маршрута убийств', 'scr_murderlv не повышает уровень с 15 до 16, если этот флаг не равен 0. Отдельные сценарии выставляют его при нарушении условий маршрута.', {0:'Последнее повышение до 16 разрешено при остальных условиях',1:'Повышение 15 → 16 заблокировано'}, 'Не исправляет уже пропущенные убийства или сюжет при ручном сбросе.'),
28: ('Ускоренная печать при удержании C', 'В объекте диалога удержание кнопки меню инициирует ускоренный пропуск текста при отсутствии выбора. Не влияет на скорость ходьбы или FPS.', {0:'Обычная печать',1:'Быстрый текст при удержании кнопки меню'}, 'Служебная опция; обычного сюжетного условия не требуется.'),
30: ('Первый Фроггит в уроке Ториэль уже появился', 'При 1 уничтожается триггер первого учебного столкновения. Сброс позволяет триггеру снова существовать, но не возвращает всю сцену Ториэль.', {0:'Триггер доступен',1:'Учебное столкновение уже запущено'}, 'Столкнуться с первым Фроггитом во время урока Ториэль.'),
31: ('Первый сдвинутый камень в Руинах', 'При загрузке комнаты камень ставится на нажатую плиту (x=280).', {0:'Камень на исходном месте',1:'Камень на плите'}, 'Толкнуть первый камень на плиту.'),
32: ('Второй сдвинутый камень в Руинах', 'Сохраняет положение второго камня на плите; не выдаёт предметов.', {0:'Исходное положение',1:'Плита прижата'}, 'Толкнуть второй камень.'),
33: ('Разговорчивый камень согласился стоять', 'При 1 восстанавливается окончательное положение говорящего камня и опускаются связанные шипы.', {0:'Переговоры ещё не завершены',1:'Камень остаётся на плите'}, 'Уговорить говорящий камень, в том числе после его попытки уйти.'),
34: ('Сколько конфет взято из миски', '0–3 управляют реакциями на взятие конфет; после четвёртой миска рассыпана. Установка числа не добавляет конфет в инвентарь.', {0:'Ни одной',1:'Взята первая',2:'Взята вторая',3:'Взята третья',4:'Конфеты рассыпаны, больше брать нельзя'}, 'Брать конфеты в боковой комнате Руин.'),
35: ('Камень открыл проход в Руинах', 'При 1 камень сдвигается на 60 пикселей и убирается связанная преграда.', {0:'Проход закрыт',1:'Камень сдвинут, преграда убрана'}, 'Решить соответствующую комнату с камнем.'),
36: ('Дружеский исход встречи с Напстаблуком', 'Включает узнавание и дружелюбные реплики Напстаблука. Значение 2 отмечает последующий разговор в Руинах.', {0:'Не подружились',1:'Развеселили в первой встрече',2:'Последующий разговор уже состоялся'}, 'Подбадривать Напстаблука в бою, затем поговорить после встречи.'),
37: ('Собака завладела телефоном Ториэль', 'Переключает ответы на телефонные звонки в ожидании Ториэль. Это не ID телефонного контакта.', {0:'До эпизода с собакой',1:'Телефон у собаки',2:'Ответ соответствующего эпизода уже обработан'}, 'Долго ждать Ториэль в комнате, где она просит оставаться.'),
41: ('Сколько раз флиртовали с Ториэль', 'Меняет ответы на флирт. После повторного вызова пункт удаляется из телефона; ненулевое значение также вспоминается в позднем разговоре.', {0:'Ещё не флиртовали',1:'Первый флирт',2:'Повторный флирт'}, 'Выбрать «Флирт» в телефоне Ториэль.'),
42: ('Ториэль назвали мамой', 'Ториэль помнит обращение «мама»; меняет дальнейший ответ на флирт. Не меняет доступность самой Ториэль.', {0:'Не называли мамой',1:'Называли мамой'}, 'Выбрать «Назвать мамой» в телефоне.'),
43: ('Повторные осмотры цветных переключателей', 'Счётчик взаимодействий. После 25 проверок появляется реплика о неловкости переключателей.', {0:'Не осматривали',26:'Порог особой реплики'}, 'Много раз осматривать переключатели в Руинах.'),
44: ('Ториэль возвращала из подвала', 'Увеличивается при попытках пройти вниз, меняет повторные реплики возвращения. Не открывает выход.', {0:'Не возвращала',1:'Первая попытка',2:'Вторая попытка',3:'Повторные попытки'}, 'Спускаться в подвал до того, как Ториэль разрешит уйти.'),
45: ('Исход встречи с Ториэль', 'Состояние Ториэль и важное условие маршрута: значение 4 требуется scr_murderlv для продолжения убийственной цепочки. Подмена не начисляет EXP или kills.', {0:'Состояние до ухода из дома',1:'Вернулась наверх',3:'Противостояние у выхода',4:'Ториэль убита',5:'Ториэль пощажена'}, 'Дойти до выхода из Руин и завершить бой выбранным способом.'),
46: ('Предпочтение вкуса пирога', 'Запоминает ответ Ториэль: корица или ириска. Вспоминается в диалогах, включая Потерянную душу; не заменяет предмет пирога.', {0:'Корица',1:'Ириска'}, 'Ответить на звонок Ториэль о вкусе пирога.'),
50: ('Известно название водяной сосиски', 'После чтения книги осмотр растения показывает его название вместо незнания персонажа.', {0:'Название неизвестно',1:'Название прочитано'}, 'Прочитать книгу о растениях в доме Ториэль.'),
51: ('Неудачи в цветной головоломке Руин', 'Считает ошибки. На 2 доступна подсказка Ториэль, последующее увеличение отмечает обработку помощи.', {0:'Ошибок нет',1:'Одна ошибка',2:'Две ошибки: условие подсказки',3:'Помощь уже обработана'}, 'Ошибаться с переключателями в Руинах.'),
52: ('Исход боя с Догго', 'Определяет судьбу Догго, его присутствие в Сноудине и условие маршрута убийств.', {0:'Бой ещё не завершён',1:'Убит',2:'Пощажён'}, 'Завершить встречу с Догго.'),
53: ('Исход боя с Догами и Догарессой', 'Значение 1 отмечает убийственный исход и нужно цепочке scr_murderlv. Значение 2 — мирное окончание.', {0:'Встреча не завершена',1:'Убийственный исход',2:'Пощажены'}, 'Закончить бой с парой собак.'),
54: ('Исход встречи с Большим Псом', 'Влияет на NPC и убийственную цепочку. 3 используется при уходе пса из-за игнорирования; это не ещё одна степень убийства.', {0:'Не завершено',1:'Убит',2:'Мирный исход',3:'Ушёл после игнорирования'}, 'Погладить/пощадить, игнорировать или убить Большого Пса.'),
55: ('Исход боя с Малым Псом', 'Сохраняет убийство или пощаду отдельно от степени поглаживания и его снежной скульптуры.', {0:'Нет завершённой встречи',1:'Убит',2:'Пощажён'}, 'Завершить бой с Малым Псом.'),
57: ('Сноудрейк: шутка и смерть', 'Значение 1 означает успешный смех после шутки, 2 — убийство. Для маршрута убийств требуется именно 2, одной квоты Сноудина недостаточно.', {0:'Шутка не поддержана',1:'Посмеялись после шутки',2:'Сноудрейк убит'}, 'Дождаться шутки и засмеяться либо убить Сноудрейка.'),
58: ('Что сложнее: путаницы или кроссворды', 'Меняет реакцию Папируса, библиотекаря и реплику Потерянной души Санса.', {0:'Детские путаницы сложнее',1:'Кроссворды сложнее'}, 'Ответить Папирусу после бумажной головоломки Санса.'),
59: ('Золото, отданное паукам', 'Накопленная сумма пожертвований/покупок, а не оставшиеся деньги. Меняет реплики пауков; сумма от 9000 меняет отношение Маффет до боя. Награда связанного сценария ограничена 999.', {0:'Не помогали',7:'Одна покупка пончика',18:'Одна покупка сидра',9999:'Крупная покупка в Хотленде'}, 'Покупать выпечку пауков или платить в бою. Присваивание не списывает золото.'),
62: ('Ответ Папирусу про спагетти', 'Запоминает заявленный ответ, хотя спагетти физически примерзли. Меняет телефонный разговор в этой комнате.', {0:'Вопрос ещё не отвечен',1:'Сказали, что съели',2:'Сказали, что оставили ему'}, 'Ответить Папирусу после комнаты со спагетти.'),
63: ('Ошибки в головоломке X/O', 'Счётчик неудачных нажатий переключателя. При >5 Санс спрашивает, почему не попросили помощи; 0 при повторном прохождении даёт другую реплику.', {0:'Решено без ошибок',6:'Порог замечания Санса'}, 'Нажимать переключатель, пока рисунок X/O неверен.'),
64: ('Следы на снежном поле с переключателем', 'Различает нетронутый снег и поиск переключателя; меняет задержку случайной встречи. Отдельный plot открывает дальнейшую историю.', {0:'Снег нетронут',-1:'Снег потревожен',1:'Переключатель найден без следов / сценарный пропуск'}, 'Ходить по снежному полю или найти переключатель.'),
65: ('30 G из снежной кучки уже забраны', 'Предотвращает повторную выдачу монет после цепочки осмотров снежных кучек. Само выставление 1 денег не выдаёт.', {0:'Награду можно получить',1:'Монеты уже получены'}, 'Осмотреть последовательность кучек до реплики о 30 G.'),
66: ('Свидание с Папирусом вместо дружеской встречи', 'При 1 дружеское мероприятие называется свиданием и меняются реплики; прогресс встречи хранится отдельно в flag[88].', {0:'Дружеская тусовка',1:'Свидание'}, 'Флиртовать с Папирусом в бою.'),
67: ('Папирус: жив, убит или повторный бой', '1 убирает живого Папируса и связанные сцены Санса, а также продвигает убийственный маршрут. Отрицательные значения используются при повторных боях после поимки. 0 само по себе не доказывает завершение боя — нужен plot.', {0:'Жив / мирный исход',1:'Папирус убит',-1:'Повторный бой: первая отметка',-2:'Повторный бой: вторая отметка',-3:'Повторный бой: третья отметка'}, 'Пощадить или убить Папируса; проигрыши меняют отрицательные отметки.'),
68: ('Переход из разговора Папируса в бой', 'Служебный переключатель сцены у тумана. Не является состоянием победы.', {0:'Начальный разговор',1:'Сцена готова запускать бой'}, 'Начать встречу с Папирусом у выхода из Сноудина.'),
73: ('Возврат из спальни гостиницы', '1 включает у хозяйки разговор после сна; после разговора сбрасывается 0. Не хранит количество ночёвок.', {0:'Обычный разговор',1:'Ожидается разговор после сна'}, 'Переночевать в гостинице Сноудина и спуститься.'),
74: ('Гифтрот получил новые украшения', 'Запоминает неприятное действие украшения Гифтрота. В SCR_TEXT также переключает набор доступных действий при связанной проверке.', {0:'Не украшали',1:'Украшали'}, 'Выбрать украшение в бою с Гифтротом.'),
75: ('Броня, о которой спрашивал Папирус', 'Копия ID экипированной брони на момент телефонного вопроса. Нужна сравнению с бронёй при встрече с Андайн; не экипирует предмет.', {}, 'Ответить на звонок Папируса о внешности. Используются ID брони из справочника предметов.'),
76: ('Ответ Папирусу про надетую броню', 'Влияет на его позднее объяснение того, что он рассказал Андайн. Отдельно хранятся ID брони в flag[75] и flag[77].', {0:'Подтвердили названную броню',1:'Сказали, что эта броня не надета'}, 'Ответить на вопрос в телефонном звонке.'),
77: ('Броня при первой погоне Андайн', 'Копия ID брони в момент начала встречи. Папирус сравнивает её с flag[75] в следующем разговоре; экипировка не меняется.', {}, 'Начать первую погоню Андайн.'),
78: ('Боевой эффект зелья на оружие', 'Отметка усиления от предмета. scr_weaponeq при оружии 14 и активном бою корректирует базовую AT; после боя флаг сбрасывается.', {0:'Усиление не активно',1:'Эффект применён в текущем бою'}, 'Использовать соответствующий предмет в бою; не сохранять как постоянный бонус.'),
80: ('Карточки Доброженого', 'Количество карточек в коробке. Покупки добавляют карточку; используются при обмене на бесплатное мороженое.', {0:'Карточек нет',1:'Одна карточка',2:'Две карточки',3:'Достаточно для обмена'}, 'Покупать Доброженое в Водопадье.'),
81: ('Шайрен: убита или концерт', '1 означает убийство и является условием маршрута убийств. 2 отмечает завершение особой последовательности концерта, меняет вид комнаты.', {0:'Нет отмеченного особого исхода',1:'Шайрен убита',2:'Концерт завершён'}, 'Убить Шайрен либо продолжать напевать с ней.'),
82: ('Собака покинула раковину Папируса', 'Открывает вариант раковины после сценки; при включённых бонусах позволяет создать дверь в бонусную комнату.', {0:'Сценка ещё доступна',1:'Раковина открыта'}, 'Осмотреть раковину в доме Папируса; начало его свидания также выставляет 1.'),
83: ('20 G из дивана получены', 'Запрещает повторное получение монет из дивана Папируса. Установка 1 не выдаёт деньги.', {0:'Монеты ещё лежат',1:'Монеты забраны'}, 'Осмотреть диван в доме Папируса.'),
85: ('Персонаж несёт зонт', 'Меняет спрайт зонта и реплики NPC; даёт специальную цену Доброженого и возможность укрыть статую. Это не предмет из восьми слотов.', {0:'Без зонта',1:'Зонт в руках'}, 'Взять зонт из корзины, вернуть его или поставить на статую.'),
86: ('Статуя укрыта зонтом и играет музыку', 'Включает музыкальную шкатулку. После ожидания у статуи появляется подсказка для пианино. Не решает пианино автоматически.', {0:'Статуя под дождём',1:'Зонт установлен, музыка играет'}, 'Принести зонт из корзины и предложить его статуе.'),
88: ('Прогресс дружбы/свидания с Папирусом', 'Хранит этап необязательной встречи. 4 — завершённая дружба, используемая дальнейшими условиями пацифистской ветки. Не воскрешает убитого Папируса.', {0:'Встреча не назначена',1:'Пригласил к дому',2:'Впустил в дом',3:'Вошли в его комнату',4:'Дружеская встреча завершена'}, 'Пощадить Папируса, вернуться к дому и пройти встречу до конца.'),
89: ('Обед с Сансом в Гриллби', '1 позволяет создать Санса для ресторанной сцены, 2 включает реплику о следующей встрече.', {0:'Приглашение ещё не принято',1:'Обед начат',2:'Обед завершён'}, 'Принять приглашение Санса на его посту.'),
94: ('Музыка Напстаблука вне его дома', 'Временный выбор воспроизводимой музыки. Ненулевое значение вместе с flag[95]=0 позволяет запустить особую встречу Аарона и Вошуа. Загрузчик безусловно сбрасывает его в 0.', {0:'Музыка выключена',1:'Первая особая музыкальная ветка',2:'Вторая особая музыкальная ветка'}, 'Включить музыку у Напстаблука и выйти из дома, не загружаясь.'),
95: ('Аарон и Вошуа напуганы призрачной музыкой', 'Запоминает завершение особого эпизода после музыки Напстаблука. Аарон меняет внешность/реплики и боится призраков; повторный триггер отключается.', {0:'Эпизод не пройден',1:'Эпизод завершён'}, 'Включить музыку у Напстаблука и попасть в нужную встречу за пределами дома.'),
96: ('Темы Герсона про Дельта-руну', 'Последовательно открывает разговоры об эмблеме и пророчестве в магазине.', {0:'Та эмблема',1:'Значение эмблемы (новое)',2:'Пророчество (новое)',3:'Темы уже обсуждены'}, 'Последовательно выбирать новые темы разговора у Герсона.'),
97: ('Эхо-цветок уже упомянул «друга позади»', 'При первом чтении говорит о друге с жуткой улыбкой; повторно спрашивает, куда он делся. Это отметка реплики, не вызов Флауи.', {0:'Первая реплика ещё не прочитана',1:'Повторная реплика'}, 'Прочитать соответствующий эхо-цветок в Водопадье.'),
98: ('Исход сцены Монстрёнка на мосту', '1 — спасение Монстрёнка; 2 — исход, после которого он не хочет разговаривать, а стартовые HP Андайн снижаются с 1500 до 1400. 0 — нет спасения в записанной сцене. Также меняет обвинение Андайн перед боем.', {0:'Нет отметки спасения',1:'Монстрёнок спасён персонажем',2:'Монстрёнка спасла Андайн и получила урон'}, 'В сцене на мосту помочь Монстрёнку либо довести альтернативный исход.'),
99: ('Номер/стадия повторного боя с Андайн', 'Счётчик заходов в бой и достигнутых уроков. Вступления 2 и 3 сокращают обучение; >3 также замедляет преследующую Андайн.', {0:'Первый бой ещё не начат',1:'Первый заход',2:'Второй этап обучения',3:'Третий этап обучения',4:'Поздняя погоня'}, 'Бежать из боя и встречаться снова; длительный бой сам поднимает некоторые этапы.'),
103: ('Пирог от Ториэль у кровати', '0 — ещё не положен, 1 — лежит у кровати, 2 — забран. При Hard Mode вид пирога другой. Не кладёт предмет в инвентарь при ручной установке.', {0:'Ещё не появился',1:'Пирог ждёт у кровати',2:'Пирог забран'}, 'Поспать в комнате дома Ториэль до plot=20, затем подобрать кусок.'),
107: ('Легендарный артефакт и надоедливая собака', '0 — артефакт доступен; 2 — временная стадия с собакой; 1 — артефакт исчез. После поглощения игра также пишет General/DB=1 в INI, поэтому одного сброса флага может быть недостаточно.', {0:'Артефакт на месте',1:'Артефакт больше недоступен',2:'Собака в процессе взаимодействия'}, 'Решить пианино, войти за артефактом и использовать/выбросить Надоедливую собаку.'),
108: ('Космические батончики из холодильника', 'Число уже взятых батончиков. Значение >2 даёт пустой холодильник; 0 показывает полное вступительное описание.', {0:'Ни одного не взяли',1:'Взят один',2:'Взято два',3:'Холодильник пуст'}, 'Забирать батончики в мусорной зоне. Ручная смена не добавляет предметы.'),
277: ('Редкий телефонный звонок уже использован', 'ОБЩИЙ флаг песни неправильного номера, странного звонка Санса и звонка про пиццу. При 1 оба телефонных объекта не создаются. Для повтора нужны 0, подходящий FUN, plot<120 и отсутствие эпилога; смены одного FUN недостаточно.', {0:'Редкий звонок ещё доступен',1:'Один из редких звонков уже использован'}, 'Пройти телефонный триггер раннего леса или причала Сноудина с подходящим FUN. Услышанный звонок блокирует остальные в этой группе.'),
279: ('Клам-гёрл уже рассказала о Сьюзи', 'При разговоре до эпилога ставится 1. Это открывает продолжение о Сьюзи в эпилоге; исчезновение дополнительно требует FUN=81 и shrine≥2. Также меняет текст осмотра фотографии в тайном подвале Санса — последствие не ограничено Клам-гёрл.', {0:'До эпилога не говорили',1:'Разговор состоялся; особый текст фотографии доступен'}, 'Найти Клам-гёрл при FUN=80–89 и поговорить до победы над Азриэлем.'),
}

FLAGS.update({
157:('Исход встречи с Mad Mew Mew','1 означает открытие бонусной комнаты. 2 записывается при мирном завершении боя; 3 — разрушенная кукла, меняется спрайт. Игра также пишет Alphys/M в INI, поэтому один флаг не полностью заменяет прохождение.',{0:'Не открыта',1:'Открыта, бой не завершён',2:'Мирный исход',3:'Кукла разбита'},'Открыть дверь под раковиной и завершить встречу с Mad Mew Mew.'),
158:('Случайный вид куклы Mew Mew','Номер кадра спрайта бонусной куклы. Выбирается при открытии двери: 0 с весом 4/9, 1 — 3/9, 2 — 2/9. Не определяет исход боя.',{0:'Кадр 0',1:'Кадр 1',2:'Кадр 2'},'Открыть бонусную дверь: игра выбирает вариант случайно.'),
159:('Золото в текущем сборе Dog Shrine','Сколько пожертвовано на текущую ступень. Когда значение достигает порога flag[160], при создании святилища счётчик обнуляется. Это не общая сумма пожертвований.',{0:'На текущую ступень ещё не пожертвовано'},'Вносить золото в коробку подношений. Порог зависит от flag[161].'),
160:('Цена следующего улучшения Dog Shrine','Вычисляется заново при входе по flag[161]. Для уровней 0–15 цены: 2, 4, 6, 8, 10, 13, 16, 19, 22, 25, 30, 35, 40, 50, 70, 0. Ручная смена будет перезаписана.',{2:'Цена первого улучшения',70:'Цена последнего улучшения',0:'Все улучшения завершены'},'Не самостоятельный прогресс: менять уровень flag[161], после входа цена пересчитается.'),
161:('Уровень обустройства Dog Shrine','Целая ступень 0–15. Управляет декорациями, ценой следующего взноса и музыкой (с уровня 6 другая тема). Не путать с config.ini ds: тот выбирает набор бонусов, а этот — развитие одного святилища.',{0:'Пустое святилище',1:'Гирлянды',2:'Данго',3:'Реклама',4:'Фотография',5:'Расширенный храм',6:'Музыкальный центр',7:'Диск',10:'Расширение коробки подношений',15:'Святилище завершено'},'Последовательно финансировать ступени, выходя и возвращаясь.'),
162:('Какие объяснения улучшений Dog Shrine уже показаны','Отметка прочитанных сообщений коробки подношений, отдельно от уровня строительства. 2 вызывает описание гирлянд при уровне 1; 3 — расширения при уровне 5; 4 — коробки при уровне 10; уровень 15 выставляет 6.',{0:'Вступление ещё не прочитано',1:'Вступление прочитано',2:'Объяснение гирлянд ожидается',3:'Гирлянды объяснены',4:'Расширение объяснено',6:'Финальная ступень'},'Осматривать коробку после очередного строительства.'),
163:('Разговор с бонусным Сансом состоялся','obj_ds4_sans при разговоре ставит 1. Сам флаг не создаёт Санса и не запускает бой.',{0:'Не говорили',1:'Говорили'},'Поговорить с Сансом в бонусном контенте 10-летия.'),
194:('Просьба передать привет Напстаблуку','В эпилоге Андайн выставляет 1 после повторных разговоров. Напстаблук при ненулевом значении отвечает на переданный привет.',{0:'Просьбы ещё нет',1:'Андайн попросила передать привет'},'Несколько раз поговорить с Андайн после финала, затем найти Напстаблука.'),
200:('Индекс регионального счётчика убийств','Это индекс другого flag, не число убийств: после боя разница kills прибавляется к global.flag[global.flag[200]]. Неверный индекс может испортить совершенно другое поле.',{202:'Начислять убийства Руинам',203:'Начислять Сноудину',204:'Начислять Водопадью',205:'Начислять Хотленду/Ядру',206:'Дополнительный региональный счётчик'},'Устанавливается объектом встречи при входе в область. Не менять вручную в середине боя.'),
201:('Число убийств на входе в бой','Копия global.kills перед боем. После возврата в мир игра начисляет разницу между kills и этой копией в региональный счётчик, выбранный flag[200]. Это не отдельная квота.',{0:'На входе убийств не было'},'Автоматически выставляется при создании obj_battler / obj_floweydraw.'),
206:('Дополнительный счётчик убийств поздней области','scr_enemynpc3 проверяет одновременно flag[205]=0 и flag[206]=0 при выборе мирного состояния NPC. Даже ненулевой 206 при нулевом 205 мешает этой проверке.',{0:'Нет отметки убийств в дополнительной области',1:'Мирная проверка scr_enemynpc3 уже не пройдена'},'Начисляется через региональный индекс flag[200], если выбран этот счётчик.'),
251:('Андайн Бессмертная побеждена','Выставляется в конце сцены её смерти вместе с flag[350]=1 и plot=122. scr_murderlv требует 251=1 и 350=1 для перехода 11 → 12.',{0:'Победы нет',1:'Андайн Бессмертная побеждена'},'Выполнить условия убийственного маршрута и победить Андайн Бессмертную.'),
252:('Радостное Чучело убито','Отличается от обычного Безумного Чучела. Значение 1 убирает его NPC и нужно scr_murderlv для перехода 9 → 10.',{0:'Нет убийства Радостного Чучела',1:'Убито'},'На убийственном маршруте убить Радостное Чучело.'),
253:('Снеговик разобран на части','Число насильно взятых кусков: 1 и 2 меняют повреждённый спрайт, ≥3 остаётся уничтоженный снеговик. Новые куски выдаются только пока ≤2.',{0:'Целый',1:'Отломан первый кусок',2:'Отломан второй',3:'Разобран полностью'},'На соответствующем маршруте повторно отбирать у снеговика куски; ручная запись не выдаёт предметы.'),
254:('Осмотрен лист с загадкой Санса','1 означает, что персонаж посмотрел на бумажную головоломку. Меняет возмущение Папируса и реплику Санса; не выбирает кошмарную картинку — её выбирает FUN.',{0:'Прошли мимо листа',1:'Лист осмотрен'},'Взаимодействовать с бумажной загадкой Санса.'),
255:('Касса магазина Сноудина ограблена','Первое ограбление пустого магазина выдаёт 758 G и ставит 1. Дальнейшие попытки отвечают «Ничего не осталось».', {0:'758 G ещё можно забрать',1:'Касса пуста'},'Осмотреть/ограбить прилавок, когда продавец покинул магазин. Смена флага денег не выдаёт.'),
})

